func NewCursors(conn *xgb.Conn, win xproto.Window) (*Cursors, error) {
	cs := &Cursors{
		conn:   conn,
		win:    win,
		m:      make(map[Cursor]xproto.Cursor),
		themeM: make(map[Cursor]xproto.Cursor),
	}
