func (cs *Cursors) initTheme() {
	if err := render.Init(cs.conn); err != nil {
		return
	}
	pictFormat, err := findARGB32PictFormat(cs.conn)
	if err != nil {
		return
	}
	theme, err := xcur.LoadThemeFromEnv()
	if err != nil {
		return
	}
	cs.pictFormat = pictFormat
	cs.theme = theme
	cs.themeSize = xcur.SizeFromEnv()
}

func (cs *Cursors) loadThemeCursor(c Cursor) (xproto.Cursor, error) {
	if cs.theme == nil {
		return 0, fmt.Errorf("xcursor theme not available")
	}
	imgs := cs.theme.Images(c.xcursorNames(), cs.themeSize)
	if len(imgs) == 0 {
		return 0, fmt.Errorf("xcursor theme cursor not found: %v", c)
	}
	if len(imgs) == 1 {
		return cs.loadThemeImage(imgs[0])
	}
	return cs.loadThemeAnimImages(imgs)
}

func (cs *Cursors) loadThemeAnimImages(imgs []*xcur.Image) (xproto.Cursor, error) {
	elts := make([]render.Animcursorelt, 0, len(imgs))
	for _, img := range imgs {
		cursor, err := cs.loadThemeImage(img)
		if err != nil {
			return 0, err
		}
		elts = append(elts, render.Animcursorelt{
			Cursor: cursor,
			Delay:  uint32(img.Delay / time.Millisecond),
		})
	}

	cursor, err := xproto.NewCursorId(cs.conn)
	if err != nil {
		return 0, err
	}
	if err := render.CreateAnimCursorChecked(cs.conn, cursor, elts).Check(); err != nil {
		return 0, err
	}
	return cursor, nil
}

func (cs *Cursors) loadThemeImage(img *xcur.Image) (xproto.Cursor, error) {
	b := img.Bounds
	w, h := b.Dx(), b.Dy()

	pixmap, err := xproto.NewPixmapId(cs.conn)
	if err != nil {
		return 0, err
	}
	if err := xproto.CreatePixmapChecked(cs.conn, 32, pixmap, xproto.Drawable(cs.win), uint16(w), uint16(h)).Check(); err != nil {
		return 0, err
	}
	defer xproto.FreePixmap(cs.conn, pixmap)

	gc, err := xproto.NewGcontextId(cs.conn)
	if err != nil {
		return 0, err
	}
	if err := xproto.CreateGCChecked(cs.conn, gc, xproto.Drawable(pixmap), 0, nil).Check(); err != nil {
		return 0, err
	}
	defer xproto.FreeGC(cs.conn, gc)

	if err := xproto.PutImageChecked(
		cs.conn,
		xproto.ImageFormatZPixmap,
		xproto.Drawable(pixmap),
		gc,
		uint16(w), uint16(h),
		0, 0,
		0,
		32,
		img.PixARGB).Check(); err != nil {
		return 0, err
	}

	picture, err := render.NewPictureId(cs.conn)
	if err != nil {
		return 0, err
	}
	if err := render.CreatePictureChecked(cs.conn, picture, xproto.Drawable(pixmap), cs.pictFormat, 0, nil).Check(); err != nil {
		return 0, err
	}
	defer render.FreePicture(cs.conn, picture)

	cursor, err := xproto.NewCursorId(cs.conn)
	if err != nil {
		return 0, err
	}
	if err := render.CreateCursorChecked(cs.conn, cursor, picture, uint16(img.Hot.X), uint16(img.Hot.Y)).Check(); err != nil {
		return 0, err
	}
	return cursor, nil
}

func findARGB32PictFormat(conn *xgb.Conn) (render.Pictformat, error) {
	reply, err := render.QueryPictFormats(conn).Reply()
	if err != nil {
		return 0, err
	}
	for _, f := range reply.Formats {
		if isARGB32PictFormat(f) {
			return f.Id, nil
		}
	}
	return 0, fmt.Errorf("argb32 pict format not found")
}

func isARGB32PictFormat(f render.Pictforminfo) bool {
	return f.Type == render.PictTypeDirect &&
		f.Depth == 32 &&
		f.Direct.RedShift == 16 &&
		f.Direct.RedMask == 0xff &&
		f.Direct.GreenShift == 8 &&
		f.Direct.GreenMask == 0xff &&
		f.Direct.BlueShift == 0 &&
		f.Direct.BlueMask == 0xff &&
		f.Direct.AlphaShift == 24 &&
		f.Direct.AlphaMask == 0xff
}

package xcur

import (
	"encoding/binary"
	"errors"
	"fmt"
	"image"
	"os"
	"time"
)

var ErrBadMagic = errors.New("bad magic")

const (
	fileMagic      = 0x72756358 // ASCII "Xcur"
	tocTypeComment = 0xfffe0001
	tocTypeImage   = 0xfffd0002
)

func DecodeFile(path string) (*Cursor, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read file: %w", err)
	}
	return Decode(b)
}

func Decode(src []byte) (*Cursor, error) {
	d := &decoder{src: src}
	return d.parse()
}

type decoder struct {
	src []byte
	pos int
}

type fileToc struct {
	typ      uint32
	subtype  uint32
	position uint32
}

func (d *decoder) parse() (*Cursor, error) {
	cursor := &Cursor{Images: map[int][]*Image{}}

	tocs, err := d.header()
	if err != nil {
		return nil, err
	}

	for _, toc := range tocs {
		if err := d.seek(int(toc.position)); err != nil {
			return nil, err
		}
		toc2, err := d.tocHeader()
		if err != nil {
			return nil, err
		}
		if toc2.typ != toc.typ || toc2.subtype != toc.subtype {
			return nil, fmt.Errorf("toc mismatch at %v", toc.position)
		}

		switch toc.typ {
		case tocTypeComment:
			comment, err := d.comment(toc)
			if err != nil {
				return nil, err
			}
			cursor.Comments = append(cursor.Comments, comment)
		case tocTypeImage:
			img, err := d.image(toc)
			if err != nil {
				return nil, err
			}
			cursor.Images[img.NominalSize] = append(cursor.Images[img.NominalSize], img)
		default:
			return nil, fmt.Errorf("unknown toc type: 0x%x", toc.typ)
		}
	}
	return cursor, nil
}

func (d *decoder) header() ([]fileToc, error) {
	magic, err := d.u32le()
	if err != nil {
		return nil, err
	}
	if magic != fileMagic {
		return nil, ErrBadMagic
	}

	if _, err := d.u32le(); err != nil { // header size
		return nil, err
	}
	if _, err := d.u32le(); err != nil { // version
		return nil, err
	}
	ntoc, err := d.u32le()
	if err != nil {
		return nil, err
	}

	tocs := make([]fileToc, 0, ntoc)
	for range ntoc {
		toc, err := d.tocEntry()
		if err != nil {
			return nil, err
		}
		tocs = append(tocs, toc)
	}
	return tocs, nil
}

func (d *decoder) tocEntry() (fileToc, error) {
	typ, err := d.u32le()
	if err != nil {
		return fileToc{}, err
	}
	subtype, err := d.u32le()
	if err != nil {
		return fileToc{}, err
	}
	position, err := d.u32le()
	if err != nil {
		return fileToc{}, err
	}
	return fileToc{typ: typ, subtype: subtype, position: position}, nil
}

func (d *decoder) tocHeader() (fileToc, error) {
	if _, err := d.u32le(); err != nil { // header size
		return fileToc{}, err
	}
	typ, err := d.u32le()
	if err != nil {
		return fileToc{}, err
	}
	subtype, err := d.u32le()
	if err != nil {
		return fileToc{}, err
	}
	if _, err := d.u32le(); err != nil { // version
		return fileToc{}, err
	}
	return fileToc{typ: typ, subtype: subtype}, nil
}

func (d *decoder) comment(toc fileToc) (*Comment, error) {
	n, err := d.u32le()
	if err != nil {
		return nil, err
	}
	b, err := d.bytesN(int(n))
	if err != nil {
		return nil, err
	}
	return &Comment{
		Subtype: CommentSubtype(toc.subtype),
		Comment: string(b),
	}, nil
}

func (d *decoder) image(toc fileToc) (*Image, error) {
	w, err := d.u32le()
	if err != nil {
		return nil, err
	}
	h, err := d.u32le()
	if err != nil {
		return nil, err
	}
	xhot, err := d.u32le()
	if err != nil {
		return nil, err
	}
	yhot, err := d.u32le()
	if err != nil {
		return nil, err
	}
	delay, err := d.u32le()
	if err != nil {
		return nil, err
	}
	if w > 1<<15 || h > 1<<15 {
		return nil, fmt.Errorf("image too large: %vx%v", w, h)
	}
	n := int(w) * int(h) * 4
	pixels, err := d.bytesN(n)
	if err != nil {
		return nil, err
	}
	img := &Image{
		NominalSize: int(toc.subtype),
		Delay:       time.Duration(delay) * time.Millisecond,
		Hot:         image.Pt(int(xhot), int(yhot)),
		Bounds:      image.Rect(0, 0, int(w), int(h)),
		PixARGB:     pixels,
	}
	return img, nil
}

